<style>
	.face {
		position: absolute;
		inset: 0;
		width: 100%;
		height: 100%;
		fill: var(--text);
	}

	.thumb {
		transform-box: fill-box;
		transform-origin: 50% 100%;
	}

	/* Pointing at the logo (or tabbing to it): the thumbs drop out of sight and pop back up,
	   left first, then right, with a little overshoot. Not for visitors who turn off motion. */
	@media (prefers-reduced-motion: no-preference) {
		:global(.home:hover) .pop .thumb,
		:global(.home:focus-visible) .pop .thumb {
			animation: pop 0.55s cubic-bezier(0.34, 1.56, 0.64, 1) backwards;
		}

		:global(.home:hover) .pop .right,
		:global(.home:focus-visible) .pop .right {
			animation-delay: 0.25s;
		}
	}

	@keyframes pop {
		from {
			opacity: 0;
			transform: translateY(40px) scale(0.8);
		}
	}
</style>
